reference.javascript:
const WINDOW_MS = 60000;
const LIMIT = 5;
const allowedTimes = new Map(); // userId -> allowed request times, oldest first

function allowRequest(userId, nowMs) {
  let times = allowedTimes.get(userId);
  if (!times) {
    times = [];
    allowedTimes.set(userId, times);
  }
  // Drop requests that are 60,000 ms old or older: they no longer count.
  while (times.length > 0 && nowMs - times[0] >= WINDOW_MS) {
    times.shift();
  }
  if (times.length >= LIMIT) {
    return false; // rejected requests are not recorded
  }
  times.push(nowMs);
  return true;
}

