const counters = new Map(); // userId -> { bucket, count }

function allowRequest(userId, nowMs) {
  const bucket = Math.floor(nowMs / WINDOW_MS);
  let entry = counters.get(userId);
  if (!entry || entry.bucket !== bucket) {
    entry = { bucket, count: 0 };
    counters.set(userId, entry);
  }
  if (entry.count >= LIMIT) {
    return false;
  }
  entry.count += 1;
  return true;
}

