reference.javascript:
// Negative when record a comes before record b in feed order.
function compareFeed(aCreatedAt, aId, bCreatedAt, bId) {
  if (aCreatedAt !== bCreatedAt) return bCreatedAt - aCreatedAt; // newest first
  if (aId < bId) return -1;
  if (aId > bId) return 1;
  return 0;
}

function encodeCursor(record) {
  return `${record.createdAt}:${record.id}`;
}

function decodeCursor(cursor) {
  const sep = cursor.indexOf(':');
  return { createdAt: Number(cursor.slice(0, sep)), id: cursor.slice(sep + 1) };
}

function paginate(records, pageSize, cursor) {
  const sorted = [...records].sort((a, b) => compareFeed(a.createdAt, a.id, b.createdAt, b.id));
  let remaining = sorted;
  if (cursor !== null) {
    const pos = decodeCursor(cursor);
    remaining = sorted.filter((r) => compareFeed(r.createdAt, r.id, pos.createdAt, pos.id) > 0);
  }
  const items = remaining.slice(0, pageSize);
  const hasMore = remaining.length > pageSize;
  return { items, nextCursor: hasMore ? encodeCursor(items[items.length - 1]) : null };
}

