function mergeBookings(bookings) {
  const sorted = [...bookings].sort((a, b) => {
    if (a.room !== b.room) return a.room < b.room ? -1 : 1;
    return a.start - b.start;
  });
  const blocks = [];
  for (const booking of sorted) {
    const last = blocks[blocks.length - 1];
    // Same room and overlapping or touching: extend the current block.
    if (last && last.room === booking.room && booking.start <= last.end) {
      last.end = Math.max(last.end, booking.end);
    } else {
      blocks.push({ room: booking.room, start: booking.start, end: booking.end });
    }
  }
  return blocks;
}

