reference.javascript:
// "19.99" -> 1999, "5" -> 500, "0.5" -> 50. No floating point involved.
function toCents(amount) {
  const [dollars, fraction = ''] = amount.split('.');
  return Number(dollars) * 100 + Number(fraction.padEnd(2, '0'));
}

function customerTotals(orders, refunds) {
  const refundedByOrder = new Map();
  for (const refund of refunds) {
    refundedByOrder.set(refund.orderId, (refundedByOrder.get(refund.orderId) || 0) + toCents(refund.amount));
  }

  const totals = new Map(); // customerId -> cents
  for (const order of orders) {
    let orderCents = 0;
    for (const line of order.lines) orderCents += toCents(line.price) * line.qty;
    const net = Math.max(0, orderCents - (refundedByOrder.get(order.orderId) || 0));
    totals.set(order.customerId, (totals.get(order.customerId) || 0) + net);
  }

  return [...totals]
    .map(([customerId, totalCents]) => ({ customerId, totalCents }))
    .sort((a, b) => {
      if (a.totalCents !== b.totalCents) return b.totalCents - a.totalCents;
      return a.customerId < b.customerId ? -1 : a.customerId > b.customerId ? 1 : 0;
    });
}

