def to_cents(amount):
    """'19.99' -> 1999, '5' -> 500, '0.5' -> 50. No floating point involved."""
    dollars, _, fraction = amount.partition(".")
    return int(dollars) * 100 + int(fraction.ljust(2, "0"))


def customer_totals(orders, refunds):
    refunded_by_order = {}
    for refund in refunds:
        order_id = refund["orderId"]
        refunded_by_order[order_id] = refunded_by_order.get(order_id, 0) + to_cents(refund["amount"])

    totals = {}  # customer_id -> cents
    for order in orders:
        order_cents = sum(to_cents(line["price"]) * line["qty"] for line in order["lines"])
        net = max(0, order_cents - refunded_by_order.get(order["orderId"], 0))
        totals[order["customerId"]] = totals.get(order["customerId"], 0) + net

    ranked = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    return [{"customerId": customer_id, "totalCents": cents} for customer_id, cents in ranked]

