reference.javascript:
// A Map keeps insertion order: the first key is the least recently used.
let capacity = 0;
let entries = new Map();

function touch(key, value) {
  entries.delete(key);
  entries.set(key, value); // re-inserted at the most recent end
}

function cacheCommand(command) {
  switch (command.op) {
    case 'init':
      capacity = command.capacity;
      entries = new Map();
      return null;
    case 'get': {
      if (!entries.has(command.key)) return null;
      const value = entries.get(command.key);
      touch(command.key, value);
      return value;
    }
    case 'put': {
      let evicted = null;
      if (!entries.has(command.key) && entries.size >= capacity) {
        evicted = entries.keys().next().value; // least recently used
        entries.delete(evicted);
      }
      touch(command.key, command.value);
      return evicted;
    }
    case 'keys':
      return [...entries.keys()].reverse();
    default:
      throw new Error(`unknown op ${command.op}`);
  }
}

