const TTL_MS = 600000;
// clientId -> Map(idempotencyKey -> { paymentId, amountCents, createdAtMs })
const keysByClient = new Map();
const createdOrder = []; // [clientId, key, createdAtMs] in creation (= time) order
let paymentCount = 0;

function dropExpired(nowMs) {
  // Entries are created in time order, so expired ones are at the front.
  while (createdOrder.length > 0 && nowMs - createdOrder[0][2] >= TTL_MS) {
    const [clientId, key, createdAtMs] = createdOrder.shift();
    const keys = keysByClient.get(clientId);
    const entry = keys && keys.get(key);
    if (entry && entry.createdAtMs === createdAtMs) keys.delete(key);
  }
}

function createPayment(clientId, idempotencyKey, amountCents, nowMs) {
  dropExpired(nowMs);
  if (!keysByClient.has(clientId)) keysByClient.set(clientId, new Map());
  const keys = keysByClient.get(clientId);
  const entry = keys.get(idempotencyKey);
  if (entry) {
    if (entry.amountCents === amountCents) return { status: 'replayed', paymentId: entry.paymentId };
    return { status: 'conflict', paymentId: null };
  }
  paymentCount += 1;
  const paymentId = `pay_${paymentCount}`;
  keys.set(idempotencyKey, { paymentId, amountCents, createdAtMs: nowMs });
  createdOrder.push([clientId, idempotencyKey, nowMs]);
  return { status: 'created', paymentId };
}

