function normalizePath(rawPath) {
  const path = rawPath.split('?')[0];
  return path
    .split('/')
    .map((segment) => (/^[0-9]+$/.test(segment) ? ':id' : segment))
    .join('/');
}

function topEndpoints(lines, k) {
  const counts = new Map();
  for (const line of lines) {
    const fields = line.split(' ');
    if (fields.length !== 5) continue; // malformed
    const endpoint = `${fields[1]} ${normalizePath(fields[2])}`;
    counts.set(endpoint, (counts.get(endpoint) || 0) + 1);
  }
  return [...counts]
    .map(([endpoint, count]) => ({ endpoint, count }))
    .sort((a, b) => b.count - a.count || (a.endpoint < b.endpoint ? -1 : a.endpoint > b.endpoint ? 1 : 0))
    .slice(0, k);
}

