function checkAccount(openingCents, overdraftLimitCents, transactions) {
  // Order: ts ascending, credits before debits at the same ts, then input order.
  const ordered = transactions
    .map((tx, index) => ({ tx, index }))
    .sort((a, b) =>
      a.tx.ts - b.tx.ts ||
      (a.tx.type === 'credit' ? 0 : 1) - (b.tx.type === 'credit' ? 0 : 1) ||
      a.index - b.index)
    .map(({ tx }) => tx);

  let balance = openingCents;
  let breachId = null;
  for (const tx of ordered) {
    balance += tx.type === 'credit' ? tx.amountCents : -tx.amountCents;
    if (breachId === null && balance < -overdraftLimitCents) {
      breachId = tx.id;
    }
  }
  return { breachId, finalCents: balance };
}

