// Small binary min-heap of strings, so picking the smallest ready name is O(log n).
class MinHeap {
  constructor() { this.items = []; }
  get size() { return this.items.length; }
  push(value) {
    const a = this.items;
    a.push(value);
    let i = a.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (a[parent] <= a[i]) break;
      [a[parent], a[i]] = [a[i], a[parent]];
      i = parent;
    }
  }
  pop() {
    const a = this.items;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let smallest = i;
        if (l < a.length && a[l] < a[smallest]) smallest = l;
        if (r < a.length && a[r] < a[smallest]) smallest = r;
        if (smallest === i) break;
        [a[smallest], a[i]] = [a[i], a[smallest]];
        i = smallest;
      }
    }
    return top;
  }
}

function migrationOrder(migrations) {
  const names = new Set(migrations.map((m) => m.name));
  const waitingOn = new Map(); // name -> number of distinct dependencies not yet run
  const dependents = new Map(); // name -> names that depend on it
  for (const m of migrations) dependents.set(m.name, []);
  for (const m of migrations) {
    const deps = new Set(m.dependsOn);
    waitingOn.set(m.name, deps.size); // an unknown dependency is never released
    for (const dep of deps) {
      if (names.has(dep)) dependents.get(dep).push(m.name);
    }
  }

  const ready = new MinHeap();
  for (const [name, count] of waitingOn) if (count === 0) ready.push(name);
  const order = [];
  while (ready.size > 0) {
    const name = ready.pop();
    order.push(name);
    for (const next of dependents.get(name)) {
      const left = waitingOn.get(next) - 1;
      waitingOn.set(next, left);
      if (left === 0) ready.push(next);
    }
  }

  const done = new Set(order);
  const blocked = migrations.map((m) => m.name).filter((name) => !done.has(name)).sort();
  return { order, blocked };
}

