    heapq.heapify(ready)
    order = []
    while ready:
        name = heapq.heappop(ready)  # smallest ready name
        order.append(name)
        for nxt in dependents[name]:
            waiting_on[nxt] -= 1
            if waiting_on[nxt] == 0:
