const SORT_FIELDS = new Set(['createdAt', 'name', 'price']);
const LIMITS = {
  page: { min: 1, max: 10000, fallback: 1 },
  limit: { min: 1, max: 100, fallback: 20 },
};

// Returns { value } or { error }.
function parseBoundedInt(raw, { min, max }) {
  if (!/^[0-9]+$/.test(raw)) return { error: 'not_an_integer' };
  const value = Number(raw);
  if (value < min || value > max) return { error: 'out_of_range' };
  return { value };
}

function parseSort(raw) {
  const sort = [];
  const seen = new Set();
  for (const item of raw.split(',')) {
    const descending = item.startsWith('-');
    const field = descending ? item.slice(1) : item;
    if (!SORT_FIELDS.has(field) || seen.has(field)) return null;
    seen.add(field);
    sort.push({ field, direction: descending ? 'desc' : 'asc' });
  }
  return sort;
}

function parseListQuery(query) {
  const errors = [];
  const result = { page: LIMITS.page.fallback, limit: LIMITS.limit.fallback, sort: [{ field: 'createdAt', direction: 'desc' }] };

  for (const [param, raw] of Object.entries(query)) {
    if (param === 'page' || param === 'limit') {
      const parsed = parseBoundedInt(raw, LIMITS[param]);
      if (parsed.error) errors.push({ param, code: parsed.error });
      else result[param] = parsed.value;
    } else if (param === 'sort') {
      const sort = parseSort(raw);
      if (sort === null) errors.push({ param, code: 'invalid_sort' });
      else result.sort = sort;
    } else {
      errors.push({ param, code: 'unknown_param' });
    }
  }

  if (errors.length > 0) {
    errors.sort((a, b) => (a.param < b.param ? -1 : a.param > b.param ? 1 : 0));
    return { ok: false, errors };
  }
  return { ok: true, page: result.page, limit: result.limit, offset: (result.page - 1) * result.limit, sort: result.sort };
}

