import re

SORT_FIELDS = {"createdAt", "name", "price"}
BOUNDS = {"page": (1, 10000), "limit": (1, 100)}
DIGITS = re.compile(r"[0-9]+")


def _parse_bounded_int(raw, low, high):
    """Returns (value, error_code)."""
    if not DIGITS.fullmatch(raw):
        return None, "not_an_integer"
    value = int(raw)
    if value < low or value > high:
        return None, "out_of_range"
    return value, None


def _parse_sort(raw):
    sort, seen = [], set()
    for item in raw.split(","):
        descending = item.startswith("-")
        field = item[1:] if descending else item
        if field not in SORT_FIELDS or field in seen:
            return None
        seen.add(field)
        sort.append({"field": field, "direction": "desc" if descending else "asc"})
    return sort


def parse_list_query(query):
    errors = []
    values = {"page": 1, "limit": 20, "sort": [{"field": "createdAt", "direction": "desc"}]}

    for param, raw in query.items():
        if param in BOUNDS:
            value, error = _parse_bounded_int(raw, *BOUNDS[param])
            if error:
                errors.append({"param": param, "code": error})
            else:
                values[param] = value
        elif param == "sort":
            sort = _parse_sort(raw)
            if sort is None:
                errors.append({"param": param, "code": "invalid_sort"})
            else:
                values["sort"] = sort
        else:
            errors.append({"param": param, "code": "unknown_param"})

    if errors:
        return {"ok": False, "errors": sorted(errors, key=lambda e: e["param"])}
    page, limit = values["page"], values["limit"]
    return {"ok": True, "page": page, "limit": limit, "offset": (page - 1) * limit, "sort": values["sort"]}

